param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop';function U($p){$n="$p`_$(Get-Random -Minimum 100000 -Maximum 999999)";$r=Invoke-RestMethod "$BaseUrl/api/auth/register" -Method Post -ContentType application/json -Body (@{username=$n;password='RateIso_2026'}|ConvertTo-Json);@{h=@{Authorization="Bearer $($r.data.token)"}}};function Setup($u){$a=Invoke-RestMethod "$BaseUrl/api/addresses" -Method Post -Headers $u.h -ContentType application/json -Body '{"receiverName":"Rate","phone":"13800138000","province":"上海市","city":"上海市","district":"浦东新区","detail":"隔离","defaultAddress":true}';$c=Invoke-RestMethod "$BaseUrl/api/cart-items" -Method Post -Headers $u.h -ContentType application/json -Body '{"productId":3,"quantity":1}';@{a=$a.data.id;c=$c.data.id}}
$a=U 'rate_a';$b=U 'rate_b';$sa=Setup $a;$sb=Setup $b;for($i=1;$i-le11;$i++){$t=Invoke-RestMethod "$BaseUrl/api/orders/tokens" -Method Post -Headers $a.h -ContentType application/json -Body (@{cartItemIds=@($sa.c)}|ConvertTo-Json);$last=Invoke-WebRequest "$BaseUrl/api/orders" -Method Post -Headers $a.h -ContentType application/json -Body (@{addressId=$sa.a;cartItemIds=@($sa.c);idempotencyToken=$t.data.token}|ConvertTo-Json) -SkipHttpErrorCheck};if($last.StatusCode-ne429){throw 'REDIS-023'};$t=Invoke-RestMethod "$BaseUrl/api/orders/tokens" -Method Post -Headers $b.h -ContentType application/json -Body (@{cartItemIds=@($sb.c)}|ConvertTo-Json);$ok=Invoke-WebRequest "$BaseUrl/api/orders" -Method Post -Headers $b.h -ContentType application/json -Body (@{addressId=$sb.a;cartItemIds=@($sb.c);idempotencyToken=$t.data.token}|ConvertTo-Json) -SkipHttpErrorCheck;if($ok.StatusCode-ne200){throw 'REDIS-025'};Write-Host 'PASS: rate limit isolated per user.'
